   517          {
   518            if (__glibc_unlikely (pattern[0] == '\0'))
   519              {
   520                dirs.gl_pathv = NULL;
   521                goto no_matches;
   522              }
   523
   524            filename = pattern;
   525            dirname = (char *) ".";
   526            dirlen = 0;
   527          }
   528      }
