   535        dirlen = 1;
   536        ++filename;
   537      }
   538    else
   539      {
   540        char *newp;
   541        dirlen = filename - pattern;
   542  #if defined __MSDOS__ || defined WINDOWS32
   543        if (*filename == ':'
   544            || (filename > pattern + 1 && filename[-1] == ':'))
   545          {
   546            char *drive_spec;
