   561        if (glob_use_alloca (alloca_used, dirlen + 1))
   562          newp = alloca_account (dirlen + 1, alloca_used);
   563        else
   564          {
   565            newp = malloc (dirlen + 1);
   566            if (newp == NULL)
   567              return GLOB_NOSPACE;
   568            malloc_dirname = 1;
   569          }
